/**
 * Why Green's theorem works — argued by tiling and cancellation.
 * A rotational field, its boundary loop, a grid of cells: the shared interior
 * edges cancel, each cell measures the local curl, and the sum is the double integral.
 */

// ── shared setup: a rotational field whose spin the student can turn up or reverse ──
const k = M.parameter("k", 1, { range: [-2, 2] });          // strength of rotation, draggable
const F = Field.vectorField((x, y) => [-k.value * y, x], { label: "F" });  // curl = 1 + k

const R = Field.rectangle({ x0: 0, y0: 0, x1: 2, y1: 2, label: "R" });
const C = R.boundary;                                        // dR, oriented CCW, minted with R

const fieldView = View.field(F, { domain: [-0.5, 2.5], range: [-0.5, 2.5] });

lesson.beat("Circulation around the loop");

const loopView = View.loop(C, { label: "C" });
lesson.show(Layout.overlay([fieldView, loopView]));
const circ = Field.circulation(F, C, { label: "\\oint_C F\\cdot dr" });
lesson.show(View.readout(circ, { label: "circulation around C" }));
lesson.say`The left side of Green's theorem is the circulation ${circ}: walk the closed curve ${C} counterclockwise around region ${R}, and total up how much the field ${F} pushes you along.`;

lesson.beat("Chop the region into cells");

const grid = Field.tile(R, { n: 6 });
const tilingView = View.tiling(grid, { domain: [-0.5, 2.5], range: [-0.5, 2.5], cellsMode: "deferred" });
lesson.show(Layout.overlay([fieldView, tilingView]));
lesson.demonstrate(Field.walkTiles(F, grid), { pace: { start: "slow", end: "fast" } });
lesson.say`Now tile ${R} into a grid of tiny cells. Give each cell its OWN little counterclockwise loop, and walk every one of them.`;

lesson.beat("Interior edges cancel");

const shared = grid.interiorEdges[0];        // one interior edge, held by two neighbor cells
lesson.focus(grid.interiorEdges, { emphasize: "agreement" });
const cShared = Field.contribution(F, shared);
const cSharedRev = Field.contribution(F, shared.reversed());
lesson.show(View.readout(cShared, { label: "shared edge, one side", compareTo: cSharedRev }));
lesson.say`Look at any of the ${grid.interiorEdges}: it belongs to two neighboring cells, walked UP by one and DOWN by the other. So ${cShared} and ${cSharedRev} are equal and opposite — every interior edge cancels against its twin.`;

lesson.beat("Only the boundary survives");

lesson.focus(grid.boundaryEdges, { emphasize: "stillness" });
const sumOfCells = M.derived(
  () => grid.tiles.reduce((s, t) => s + Field.circulation(F, t.boundary).value, 0),
  "\\sum_{cells}\\oint circulation"
);
lesson.show(View.readout(sumOfCells, { label: "sum of all cell loops", compareTo: circ }));
lesson.say`After all the interior cancellation, the only edges left are the ${grid.boundaryEdges} — and together they ARE the outer loop ${C}. So the sum of every cell's circulation equals the boundary circulation ${circ}.`;

lesson.beat("One cell's spin is curl");

const cell = grid.tile(2, 3);
const cellView = View.loop(cell.boundary, { label: "one cell" });
lesson.show(Layout.overlay([fieldView, cellView]));
const cellCirc = Field.circulation(F, cell.boundary, { label: "cell circulation" });
const curlTimesArea = M.derived(
  () => F.curlAt(cell.boundary.points()[0][0] + 0.166, cell.boundary.points()[0][1] + 0.166).value * cell.area.value,
  "(\\partial_x Q - \\partial_y P)\\cdot area"
);
const cellClaim = M.claim({
  lhs: cellCirc,
  rhs: curlTimesArea,
  relation: "≈",
  tolerance: 0.02,
  label: "cell circulation = curl \\cdot area",
});
lesson.show(View.claim(cellClaim));
lesson.say`Zoom into one cell. Its net circulation per unit area is exactly the curl, ${F.curlAt(1.166, 0.833)} = \\partial_x Q - \\partial_y P. So a single small loop measures the LOCAL spin of the field times the cell's ${cell.area}.`;

lesson.beat("Add up all the spins");

lesson.expose(k, { as: "sliders" });
const doubleIntegral = M.derived(
  () => grid.tiles.reduce((s, t) => s + (1 + k.value) * t.area.value, 0),
  "\\iint_R (\\partial_x Q - \\partial_y P)\\, dA"
);
const green = M.claim({
  lhs: circ,
  rhs: doubleIntegral,
  relation: "≈",
  tolerance: 0.05,
  label: "\\oint_C F\\cdot dr = \\iint_R (\\partial_x Q - \\partial_y P)\\, dA",
});
lesson.show(View.claim(green));
lesson.say`Add each cell's curl-times-area over the whole grid, and that sum becomes the ${doubleIntegral}. Because the interior all cancelled, the surviving boundary circulation ${circ} equals it exactly. Drag ${k} to spin the field harder or reverse it — both sides move together and the badge never breaks. That is Green's theorem.`;
```
